// --- AI HELPER ---
const getRoomCodeFromLocation = () => {
    if (typeof window === 'undefined') return '';
    try {
        return String(new URLSearchParams(window.location.search).get('room') || '').trim().toUpperCase();
    } catch {
        return '';
    }
};

const generateAIContent = async (type, context) => {
    try {
        const roomCode = getRoomCodeFromLocation();
        return await generateAiContentRequest({
            type,
            context,
            roomCode,
            usageSource: `host_${type}`
        });
    } catch (e) {
        hostLogger.error('AI Error', e);
        const code = String(e?.code || e?.message || '').toLowerCase();
        const degradationMessage = getUsageDegradationMessageForError(e, { capabilityId: 'ai_generation', surface: 'host' });
        if (degradationMessage) {
            alert(degradationMessage);
        } else if (code.includes('permission-denied')) {
            alert("AI tools require an active Host subscription.");
        } else {
            alert("AI generation is unavailable right now. Check function secrets and deployment.");
        }
        return null;
    }
};

const LOCAL_DB_NAME = 'bross_local_media';
const LOCAL_STORE = 'videos';

const openLocalDb = () => new Promise((resolve, reject) => {
    const req = indexedDB.open(LOCAL_DB_NAME, 1);
    req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(LOCAL_STORE)) {
            db.createObjectStore(LOCAL_STORE, { keyPath: 'id' });
        }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
});

const getLocalVideos = async () => {
    const db = await openLocalDb();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(LOCAL_STORE, 'readonly');
        const store = tx.objectStore(LOCAL_STORE);
        const req = store.getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = () => reject(req.error);
    });
};

const saveLocalVideo = async (entry = {}) => {
    const db = await openLocalDb();
    const safeTitle = String(entry.title || '').trim();
    const safeBlob = entry.blob;
    if (!safeTitle || !safeBlob) throw new Error('title and blob are required');
    const payload = {
        id: String(entry.id || `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`),
        title: safeTitle,
        artist: String(entry.artist || 'Offline Backup').trim() || 'Offline Backup',
        fileName: String(entry.fileName || `${safeTitle}.media`).trim() || `${safeTitle}.media`,
        mediaType: String(entry.mediaType || (((safeBlob.type || '').startsWith('audio/')) ? 'audio' : 'video')).trim() || 'video',
        blob: safeBlob,
        size: Number(entry.size || safeBlob.size || 0) || 0,
        offlineReady: entry.offlineReady !== false,
        createdAtMs: Math.max(0, Number(entry.createdAtMs || Date.now()) || Date.now())
    };
    return new Promise((resolve, reject) => {
        const tx = db.transaction(LOCAL_STORE, 'readwrite');
        const store = tx.objectStore(LOCAL_STORE);
        const req = store.put(payload);
        req.onsuccess = () => resolve(payload);
        req.onerror = () => reject(req.error);
    });
};

const deleteLocalVideo = async (id = '') => {
    const safeId = String(id || '').trim();
    if (!safeId) return;
    const db = await openLocalDb();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(LOCAL_STORE, 'readwrite');
        const store = tx.objectStore(LOCAL_STORE);
        const req = store.delete(safeId);
        req.onsuccess = () => resolve(true);
        req.onerror = () => reject(req.error);
    });
};

