                mediaUrl: String(item?.mediaUrl || item?.url || '').trim(),
                mediaType: String(item?.mediaType || (isAudioUrl(item?.url || item?.mediaUrl || '') ? 'audio' : 'video')).trim() || 'video',
                offlineReady: item?._local === true || item?.offlineReady === true,
                playable: true,
