        if (!sourceId) return;
        const syncKey = `${roomCode}:${sourceId}:${appleMusicAutoSourceType}:${appleMusicAutoPlaybackUrl}`;
        if (appleMusicRoomDefaultSyncRef.current === syncKey) return;
        appleMusicRoomDefaultSyncRef.current = syncKey;
