    const prepareHostStorageWrite = useCallback(async (forceRefresh = false) => {
        const appCheckReady = await ensureAppCheckToken(forceRefresh).catch(() => false);
        const currentUser = auth.currentUser;
        if (typeof currentUser?.getIdToken === 'function') {
            await currentUser.getIdToken(forceRefresh).catch(() => null);
        }
        if (!appCheckReady && !forceRefresh) {
            return prepareHostStorageWrite(true);
        }
        return {
            appCheckReady,
            authUid: String(currentUser?.uid || '').trim()
        };
    }, []);
    const uploadLogoFile = async (file) => {
        if (!roomCode) {
            toast('Create or open a room first');
            return;
        }
        if (!file) return;
        if (!file.type?.startsWith('image/')) {
            toast('Please select an image file');
            return;
        }
        const maxBytes = 12 * 1024 * 1024;
        if (file.size > maxBytes) {
            toast('Logo is too large (max 12 MB)');
            return;
        }
        setLogoUploading(true);
        setLogoUploadProgress(0);
        try {
            const ext = (file.name.split('.').pop() || 'png').toLowerCase().replace(/[^a-z0-9]/g, '') || 'png';
            const stem = (file.name.replace(/\.[^/.]+$/, '') || 'logo')
                .toLowerCase()
                .replace(/[^a-z0-9_-]+/g, '-')
                .replace(/-+/g, '-')
                .slice(0, 60);
            const storagePath = `room_branding/${roomCode}/${nowMs()}-${stem}.${ext}`;
            const fileRef = storageRef(storage, storagePath);
            await prepareHostStorageWrite();
            await uploadBytes(fileRef, file, {
                contentType: file.type,
                cacheControl: 'public,max-age=604800'
            });
            setLogoUploadProgress(100);
            const url = await getDownloadURL(fileRef);
            setLogoUrl(url);
            await persistLogoLibrary([url, ...logoLibrary]);
            await updateRoom({ logoUrl: url });
            toast('Logo uploaded and applied');
        } catch (e) {
            hostLogger.error('Logo upload failed', e);
            toast('Logo upload failed');
        } finally {
            setLogoUploading(false);
            setLogoUploadProgress(0);
            if (logoInputRef.current) logoInputRef.current.value = '';
        }
    };
