                active: true,
                id: `media_scene_${startedAtMs}`,
                type: 'media_scene',
                title: getRoomMediaTitle(item),
                headline: getRoomMediaTitle(item),
                subhead: '',
                takeoverScene: 'media_scene',
                accentTheme: 'cyan',
