        setClosingRoom(true);
        let roomClosed = false;
        try {
            const closedAtMs = nowMs();
            const reactionSnap = await getDocs(query(collection(db, 'artifacts', APP_ID, 'public', 'data', 'reactions'), where('roomCode', '==', roomCode)));
            const reactions = reactionSnap.docs.map(d => ({ id: d.id, ...d.data() }));
            const crowdSelfieSnap = await getDocs(query(collection(db, 'artifacts', APP_ID, 'public', 'data', 'crowd_selfie_submissions'), where('roomCode', '==', roomCode)));
            const crowdSelfies = crowdSelfieSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
            const promptVoteSnap = await getDocs(query(collection(db, 'artifacts', APP_ID, 'public', 'data', 'prompt_votes'), where('roomCode', '==', roomCode)));
            const promptVotes = promptVoteSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
            const tournament = (() => {
                const roomSummary = room?.bracketLastSummary || null;
                if (roomSummary?.summaryVersion) {
                    const hasMoments = (roomSummary?.matchHistory || []).length > 0 || !!roomSummary?.championName;
                    return hasMoments ? roomSummary : null;
                }
                const liveBracket = room?.karaokeBracket || null;
                if (!liveBracket?.rounds?.length) return null;
                const built = buildBracketSummary({ ...liveBracket, roomCode });
                const hasMoments = (built?.matchHistory || []).length > 0 || !!built?.championName;
                return hasMoments ? built : null;
            })();
            const tournamentMoments = (tournament?.timeCapsule?.moments || []).slice(0, 8).map((moment) => ({
                id: moment.id || `tournament_moment_${Math.random().toString(36).slice(2, 7)}`,
                icon: EMOJI.trophy || EMOJI.star,
                text: moment.text || 'Tournament moment',
                user: tournament?.championName || 'Tournament',
                    timestamp: moment?.at || nowMs()
                }));
            const recap = buildRoomRecapSummary({
                roomCode,
                room,
                songs,
                users,
                reactions,
                activities,
                crowdSelfies,
                promptVotes,
                generatedAtMs: closedAtMs,
                source: 'room_close',
                window: {
                    endMs: closedAtMs,
                    endUtc: new Date(closedAtMs).toISOString()
                }
            });
            recap.tournament = tournament;
            recap.highlights = [...tournamentMoments, ...(recap.highlights || [])].slice(0, 30);

            const roomPatch = { closedAt: closedAtMs, recap };
            await updateRoom(roomPatch);
            roomClosed = true;

            const publicRecapAllowed = room?.publicRoom === true
                || room?.discover?.publicRoom === true
                || String(room?.discover?.visibility || '').trim().toLowerCase() === 'public';
            if (!publicRecapAllowed) {
                toast('Room closed. Recap saved privately.');
                return;
            }
            const publishedRecap = await publishPublicRoomRecap({
                roomCode,
                origin: audienceBase || (typeof window !== 'undefined' ? window.location.origin : ''),
            });
            const recapUrl = String(publishedRecap?.publicUrl || '').trim() || buildRoomRecapUrl(roomCode, audienceBase || window.location.origin);
            await navigator.clipboard.writeText(recapUrl);
            toast('Room closed. Public recap link copied.');
        } catch (e) {
            hostLogger.error(e);
            if (roomClosed) {
                const fallbackPreviewUrl = audienceBase
                    ? `${audienceBase}?room=${encodeURIComponent(roomCode)}&mode=recap`
                    : `${window.location.origin}?room=${encodeURIComponent(roomCode)}&mode=recap`;
                try {
                    await navigator.clipboard.writeText(fallbackPreviewUrl);
                } catch {
                    // Ignore clipboard fallback errors.
                }
                toast('Room closed, but public recap publish failed.');
            } else {
                toast('Recap failed');
            }
        } finally {
            setClosingRoom(false);
        }
