                                        const lastActiveMs = u.lastActiveAt?.seconds ? u.lastActiveAt.seconds * 1000 : u.lastActiveAt;
                                        const userTight15Preview = sanitizeTight15List(u.tight15 || u.tight15Temp || []).slice(0, 3);
