                                        setChatTvMode={setChatTvMode}
                                        chatSlowModeSec={chatSlowModeSec}
                                        setChatSlowModeSec={setChatSlowModeSec}
                                        handleChatViewMode={handleChatViewMode}
                                        chatViewMode={chatViewMode}
